def sum_recursive(numbers):
    if not numbers:
        return 0
    first = numbers[0]
    rest = numbers[1:]
    return first + sum_recursive(rest)

print(sum_recursive([3,1,4,1,5,9]))

def find_min(arr):
    if len(arr) == 0:
        return None
    min_val = arr[0]
    for num in arr[1:]:
        if num < min_val:
            min_val = num
    return min_val

